-- Ajustes dos cenários iniciais após a primeira bateria de testes com a IA:
-- troca de profissional e desmarcação pediam dados que a equipe coleta; urgência não deve trazer primeiros socorros.
UPDATE ai_scenarios SET guidance='1) Acolha sem julgar o profissional atual. 2) Diga que a coordenação clínica vai avaliar a troca e falar com a família. 3) Encaminhe já para a fila clinica com motivo OPERATIONAL_ACTION, registrando no resumo o motivo se a família disse. 4) Não peça nome, cadastro nem motivo: a coordenação faz isso.',version=version+1,updated_at=now() WHERE title='Troca de profissional' AND created_by IS NULL;
UPDATE ai_scenarios SET guidance='1) Agradeça o aviso. 2) Diga que a agenda vai registrar e confirmar com a família (e propor novo horário, se for remarcação). 3) Encaminhe já para a fila agenda com motivo OPERATIONAL_ACTION, registrando no resumo o dia e a terapia citados. 4) Não peça nome nem detalhes: a recepção localiza pelo contato.',version=version+1,updated_at=now() WHERE title='Desmarcar ou remarcar sessão' AND created_by IS NULL;
UPDATE ai_scenarios SET avoid='Não avalie a gravidade, não sugira esperar, não dê instruções de primeiros socorros nem de medicação e não peça dados de cadastro antes da orientação de emergência.',version=version+1,updated_at=now() WHERE title='Relato de urgência ou risco' AND created_by IS NULL;
INSERT INTO ai_scenario_versions(tenant_id,scenario_id,version,snapshot) SELECT tenant_id,id,version,to_jsonb(s) FROM ai_scenarios s WHERE created_by IS NULL AND version=2 AND title IN('Troca de profissional','Desmarcar ou remarcar sessão','Relato de urgência ou risco') ON CONFLICT DO NOTHING;
